int push(DArrayStack *ptr, int data)
{
    if (ptr == NULL)
    {
        return -1;
    }
    if (ptr->top == (ptr->capacity) - 1)
    {
        DArrayStack *result = double_array(ptr, ptr->capacity);
        if (result == NULL)
        {
            return -1;
        }
        ptr->top++;
        ptr->arrPtr[ptr->top] = data;
    }
    else
    {
        ptr->top++;
        ptr->arrPtr[ptr->top] = data;
    }
    return ptr->top;
}


